package com.aurum.scalp;
import org.junit.Test;import static org.junit.Assert.*;
import org.json.*;import java.util.*;import java.nio.charset.StandardCharsets;

public class BiquoteTest {
    private static final long NOW=java.time.Instant.parse("2026-11-14T14:40:00Z").toEpochMilli();
    private String fixture(String name)throws Exception{try(java.io.InputStream in=getClass().getResourceAsStream("/biquote/"+name+".json")){return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}
    @Test public void actualClosedMarketQuoteIsNotLive()throws Exception{Market.Quote q=BiquoteCodec.quote(fixture("quote"),NOW);assertEquals(3882.979,q.bid,0);assertEquals(3883.063,q.mid(),.000001);assertEquals("● MARKET CLOSED",Market.quoteState(q,true,NOW));}
    @Test public void wrongSymbolCannotPolluteGoldQuote()throws Exception{JSONObject j=new JSONObject(fixture("quote")).put("symbol","BTCUSDT");try{BiquoteCodec.quote(j,NOW);fail();}catch(java.io.IOException expected){}}
    @Test public void invalidAndFutureTicksAreRejected()throws Exception{for(JSONObject j:Arrays.asList(new JSONObject(fixture("quote")).put("bid",5000),new JSONObject(fixture("quote")).put("timestamp",java.time.Instant.ofEpochMilli(NOW+120000).toString()))){try{BiquoteCodec.quote(j,NOW);fail();}catch(java.io.IOException expected){}}}
    @Test public void shortRealHourlyHistoryWorksAndRemainsShort()throws Exception{List<Market.Candle>b=BiquoteCodec.candles(fixture("1h"),Market.Frame.H1,NOW,80);assertEquals(168,b.size());assertTrue(ZoneEngine.calculate(b,Market.Frame.H1,NOW).candles.size()<480);}
    @Test public void latestOpenMarkedFridayBarStaysExcludedSaturday()throws Exception{for(Market.Frame f:Market.Frame.values()){String n=BiquoteCodec.interval(f);JSONObject j=new JSONObject(fixture(n));List<Market.Candle>b=BiquoteCodec.candles(j.toString(),f,NOW,80);long open=0;for(int i=0;i<j.getJSONArray("bars").length();i++){JSONObject row=j.getJSONArray("bars").getJSONObject(i);if(row.getBoolean("isOpen"))open=BiquoteCodec.timestamp(row.getString("openTime"));}final long pending=open;assertTrue(open>0);assertTrue(b.stream().noneMatch(c->c.time==pending));}}
    @Test public void cannotMarkFutureOrMisalignedBarClosedByFlag()throws Exception{JSONObject j=new JSONObject(fixture("4h"));JSONArray a=new JSONArray().put(j.getJSONArray("bars").getJSONObject(1).put("isOpen",false).put("openTime","2026-11-14T16:00:00Z"));j.put("bars",a);assertTrue(BiquoteCodec.candles(j.toString(),Market.Frame.H4,NOW,0).isEmpty());a.getJSONObject(0).put("openTime","2026-11-13T17:00:00Z");assertTrue(BiquoteCodec.candles(j.toString(),Market.Frame.H4,NOW,0).isEmpty());}
    @Test public void unknownOpenFlagIsNotAssumedClosed()throws Exception{JSONObject j=new JSONObject(fixture("1h"));JSONArray a=j.getJSONArray("bars");for(int i=0;i<a.length();i++)a.getJSONObject(i).remove("isOpen");assertTrue(BiquoteCodec.candles(j.toString(),Market.Frame.H1,NOW,0).isEmpty());}
    @Test public void wrongIntervalCannotBecomeFourHourHistory()throws Exception{try{BiquoteCodec.candles(fixture("1h"),Market.Frame.H4,NOW,0);fail();}catch(java.io.IOException expected){}}
    @Test public void historyMergePreservesOlderBarsAndAppliesCorrections()throws Exception{List<Market.Candle>n=BiquoteCodec.candles(fixture("1h"),Market.Frame.H1,NOW,80);Market.Candle first=n.get(0),older=new Market.Candle(first.time-3600000,4000,4001,3999,4000,first.time);List<Market.Candle>merged=BiquoteCodec.merge(Arrays.asList(older,first),n,fixture("1h"),Market.Frame.H1,1000);assertEquals(169,merged.size());assertSame(older,merged.get(0));assertEquals(168,BiquoteCodec.merge(merged,n,fixture("1h"),Market.Frame.H1,168).size());}
    @Test public void reopenedProviderBarIsRemovedFromCache()throws Exception{List<Market.Candle>n=BiquoteCodec.candles(fixture("1h"),Market.Frame.H1,NOW,80);JSONObject j=new JSONObject(fixture("1h"));for(int i=0;i<j.getJSONArray("bars").length();i++)j.getJSONArray("bars").getJSONObject(i).put("isOpen",true);assertTrue(BiquoteCodec.merge(n,Collections.emptyList(),j.toString(),Market.Frame.H1,1000).isEmpty());}
    @Test public void sampleMinuteMatchesMidTicksNotBid()throws Exception{JSONArray ticks=new JSONArray(fixture("tick_history"));JSONObject row=null;JSONArray rows=new JSONObject(fixture("1m")).getJSONArray("bars");for(int i=0;i<rows.length();i++)if(rows.getJSONObject(i).getString("openTime").equals("2026-11-13T21:57:00Z"))row=rows.getJSONObject(i);double high=0,low=Double.MAX_VALUE,last=0;int count=0;for(int i=0;i<ticks.length();i++){JSONObject t=ticks.getJSONObject(i);if(t.getString("timestamp").startsWith("2026-11-13T21:57:")){double mid=(t.getDouble("bid")+t.getDouble("ask"))/2;high=Math.max(high,mid);low=Math.min(low,mid);last=mid;count++;}}assertEquals(84,count);assertNotNull(row);assertEquals(row.getDouble("high"),high,.000001);assertEquals(row.getDouble("low"),low,.000001);assertEquals(row.getDouble("close"),last,.000001);}
    @Test public void referenceAndProximityUseMidNotBid()throws Exception{Market.Quote q=new Market.Quote(NOW,4002,4006);assertEquals(4004,Market.referencePrice(q,Collections.emptyList()),0);Market.Frame f=Market.Frame.M5;long close=NOW/300000*300000;ZoneEngine.Zone z=new ZoneEngine.Zone(f,3999,4001,2,true,false,false,3,close,close);ZoneEngine.Analysis a=new ZoneEngine.Analysis(f,Collections.singletonList(new Market.Candle(close-300000,4000,4010,3990,4000)),Collections.singletonList(z),Collections.emptyList(),10,0,"range");SmartAlerts s=new SmartAlerts();s.evaluate(new Market.Quote(NOW-5000,4010,4010.1),true,NOW-5000,Collections.singletonMap(f,a),Collections.singletonMap(f,NOW-5000),EnumSet.of(f));assertTrue(s.evaluate(q,true,NOW,Collections.singletonMap(f,a),Collections.singletonMap(f,NOW),EnumSet.of(f)).isEmpty());assertTrue(s.evaluate(new Market.Quote(NOW+1000,4001,4001.1,true,false),true,NOW+1000,Collections.singletonMap(f,a),Collections.singletonMap(f,NOW),EnumSet.of(f)).isEmpty());}
}
